// Generated by scripts/google-vendor.ts from shared/google-tools; edit the original and rerun it.
// Drive tools shaped for agents: search across every linked account in plain words, and read any
// file as text, exporting Google Docs, Sheets and Slides on the way.
import { number, object, query, string } from "apps";
import { defined, fanOut, google, googleText, select, single, type Base, type Context, type Source, type Target } from "./shared.js";

const base = "https://www.googleapis.com/drive/v3";
const account = string().optional();
const fields = "id,name,mimeType,modifiedTime,size,webViewLink,owners(emailAddress),parents,shared";

const kinds: Record<string, string> = {
  doc: "application/vnd.google-apps.document",
  sheet: "application/vnd.google-apps.spreadsheet",
  slides: "application/vnd.google-apps.presentation",
  form: "application/vnd.google-apps.form",
  folder: "application/vnd.google-apps.folder",
  pdf: "application/pdf",
};

const quote = (text: string) => `'${text.replaceAll("\\", "\\\\").replaceAll("'", "\\'")}'`;

/** Drive query language passes through; plain words search names and contents. */
const driveQuery = (text: string | undefined, kind: string | undefined) => {
  const clauses = ["trashed = false"];
  const trimmed = text?.trim();
  if (trimmed) {
    const raw = /\b(contains|in parents|in owners|mimeType|modifiedTime|sharedWithMe|starred)\b|[=<>]/.test(trimmed);
    clauses.push(raw ? `(${trimmed})` : `(name contains ${quote(trimmed)} or fullText contains ${quote(trimmed)})`);
  }
  if (kind) {
    const mimeType = kinds[kind];
    if (mimeType === undefined) throw new Error(`type must be one of ${Object.keys(kinds).join(", ")}.`);
    clauses.push(`mimeType = ${quote(mimeType)}`);
  }
  return clauses.join(" and ");
};

const file = (target: Target, item: any) =>
  defined({
    account: target.email,
    fileId: item.id as string,
    name: item.name as string,
    type: (Object.entries(kinds).find(([, mime]) => mime === item.mimeType)?.[0] ?? item.mimeType) as string,
    modified: item.modifiedTime as string,
    owner: item.owners?.[0]?.emailAddress as string | undefined,
    size: item.size === undefined ? undefined : Number(item.size),
    link: item.webViewLink as string,
  });

/** Exports for Google's own formats; other files download as they are. */
const exports: Record<string, string> = {
  "application/vnd.google-apps.document": "text/markdown",
  "application/vnd.google-apps.spreadsheet": "text/csv",
  "application/vnd.google-apps.presentation": "text/plain",
  "application/vnd.google-apps.drawing": "image/svg+xml",
  "application/vnd.google-apps.script": "application/vnd.google-apps.script+json",
};
const readable = /^(text\/|application\/(json|xml|javascript|x-yaml|yaml|csv|sql|x-sh))|\+(json|xml)$/;

const readFile = async (ctx: Base, target: Target, fileId: string, maxCharacters: number) => {
  const id = encodeURIComponent(fileId);
  const meta = await google(ctx, target, `${base}/files/${id}`, { search: { fields, supportsAllDrives: true } });
  const exportType = exports[meta.mimeType];
  let text: string;
  if (exportType) {
    try {
      text = await googleText(ctx, target, `${base}/files/${id}/export?mimeType=${encodeURIComponent(exportType)}`);
    } catch (error) {
      // Markdown export is newer than plain text; fall back where it is refused.
      if (exportType !== "text/markdown") throw error;
      text = await googleText(ctx, target, `${base}/files/${id}/export?mimeType=text/plain`);
    }
  } else if (readable.test(meta.mimeType)) {
    text = await googleText(ctx, target, `${base}/files/${id}?alt=media&supportsAllDrives=true`);
  } else {
    return { ...file(target, meta), text: null, note: `${meta.mimeType} is not text; open the link or use api.drive to download it.` };
  }
  return {
    ...file(target, meta),
    ...(meta.mimeType === "application/vnd.google-apps.spreadsheet" ? { note: "Only the first sheet is exported; use sheets.read for others." } : {}),
    truncated: text.length > maxCharacters,
    text: text.slice(0, maxCharacters),
  };
};

/** Files matching a Drive query across targets, newest first. */
export const searchFiles = async (ctx: Base, targets: readonly Target[], q: string, max: number) => {
  const { items, errors } = await fanOut(targets, async (target) => {
    const { files = [] } = await google(ctx, target, `${base}/files`, {
      search: {
        q,
        pageSize: max,
        // Drive refuses ordering a fullText search.
        orderBy: q.includes("fullText") ? undefined : "modifiedTime desc",
        fields: `files(${fields})`,
        corpora: "allDrives",
        includeItemsFromAllDrives: true,
        supportsAllDrives: true,
      },
    });
    return (files as any[]).map((item) => file(target, item));
  });
  items.sort((a, b) => b.modified.localeCompare(a.modified));
  return { files: items.slice(0, max), errors };
};

/** The curated tools and their router's metadata; `source` names the package's accounts. */
export const drive = (source: Source) => ({
  tools: {
    search: query(
      {
        description:
          "Search Drive across every linked Google account (or one), newest first. Plain words match file names and contents; Drive query syntax (name contains 'x', mimeType = '...', 'me' in owners, sharedWithMe) passes through. Leave query empty for recently modified files. type narrows to doc, sheet, slides, form, folder or pdf.",
        input: object({
          query: string().optional(),
          type: string().optional(),
          account,
          max: number().optional(),
        }),
      },
      async (ctx: Context, input) =>
        searchFiles(ctx, await select(ctx, source, input.account), driveQuery(input.query, input.type), Math.min(Math.max(input.max ?? 20, 1), 100)),
    ),
    read: query(
      {
        description:
          "Read a Drive file as text: Google Docs as Markdown, Sheets as CSV (first sheet), Slides as text, and text-like files as they are. Other files return their details and link. Long files are cut at maxCharacters (default 100000).",
        input: object({ account, fileId: string({ minLength: 1 }), maxCharacters: number().optional() }),
      },
      async (ctx: Context, input) => readFile(ctx, await single(ctx, source, input.account), input.fileId, input.maxCharacters ?? 100_000),
    ),
  },
  meta: {
    title: "Google Drive",
    description: "Find and read files across every linked Google account.",
    instructions: `search spans every linked account unless \`account\` (an address) is given; read takes the account a result came from. Uploads, sharing, comments and revisions are under ${source.api("drive")}.`,
  },
});

export { driveQuery };
